questionvariables.text:
/* Line A */
dxa: 1 + rand(3);
dya: (-1)^rand(2) * (1 + rand(5));
x1a: -3 + rand(7);
y1a: -4 + rand(9);
x2a: x1a + dxa;
y2a: y1a + dya;
ta1: dya / dxa;

/* Line B */
dxb: 1 + rand(3);
dyb: (-1)^rand(2) * (1 + rand(5));
x1b: -3 + rand(7);
y1b: -4 + rand(9);
x2b: x1b + dxb;
y2b: y1b + dyb;
ta2: dyb / dxb;

/* Part (a): even sums so mid-point is integer */
x1a: 1 + rand(6);
y1a: 1 + rand(6);
x2a: x1a + 2*(1 + rand(3));
y2a: y1a - 2*(1 + rand(3));
ta1: (x1a + x2a) / 2;
ta2: (y1a + y2a) / 2;

/* Part (b): allow half-integer mid-points, include negatives */
x1b: -(1 + rand(4));
y1b: -(1 + rand(4));
x2b: x1b + 2 + rand(5);
y2b: y1b + 2 + rand(5);
ta3: (x1b + x2b) / 2;
ta4: (y1b + y2b) / 2;

/* Worked example */
b1: 2*rand_with_step(-6, -1, 1);
c1: rand_with_step(-5, 8, 1);
ta1: (x + b1/2)^2 + c1 - (b1/2)^2;

/* Student exercise — different even coefficient */
b2: 2*rand_with_step(1, 6, 1);
c2: rand_with_step(-5, 8, 1);
ta2: (x + b2/2)^2 + c2 - (b2/2)^2;
sq2: (b2/2)^2;

/* Display helpers — avoid x + -3 rendering */
disp_q1: x^2 + b1*x + c1;
disp_q2: x^2 + b2*x + c2;
disp_lhs1: x^2 + b1*x;
disp_lhs2: x^2 + b2*x;
disp_csq1: (x + b1/2)^2 - (b1/2)^2;
disp_csq1_full: (x + b1/2)^2 - (b1/2)^2 + c1;
disp_csq2: (x + b2/2)^2 - (b2/2)^2;
disp_csq2_full: (x + b2/2)^2 - (b2/2)^2 + c2;

/* Design backwards: pick the number of crossings, then build the quadratic */
b1: 2*rand([-6,-5,-4,-3,-2,-1,1,2,3,4,5,6]);
/* Pick qval to control crossings: positive = 0, zero = 1, negative = 2 */
crossing_type: rand([0, 1, 2]);
qval: if crossing_type = 0 then rand_with_step(1, 8, 1)
      else if crossing_type = 1 then 0
      else -rand_with_step(1, 8, 1);
c1: qval + (b1/2)^2;
ta1: (x + b1/2)^2 + qval;

/* Display helpers — avoid x + -3 rendering */
disp_q1: x^2 + b1*x + c1;
disp_csq1_unsimplified: ev((x + b1/2)^2 - (b1/2)^2 + c1, simp:false);
ta2: qval;
ta3_num: if qval > 0 then 0 else if qval = 0 then 1 else 2;
ta3_opts: [["0 (does not cross)", is(ta3_num = 0)], ["1 (just touches)", is(ta3_num = 1)], ["2 (crosses twice)", is(ta3_num = 2)]];
explanation: if qval > 0 then sconcat("The minimum value is ", string(qval), " which is positive, so \\(y > 0\\) for all \\(x\\). The graph does not cross the \\(x\\)-axis.")
             else if qval = 0 then "The minimum value is 0, which means the graph just touches the \\(x\\)-axis at one point."
             else sconcat("The minimum value is ", string(qval), " which is negative, so the graph dips below the \\(x\\)-axis and crosses it twice.");

stack_include_contrib("prooflib.mac");

proof_steps: [
    ["identify",  "For the equation \\(x^2 + kx + 2k = 0\\), we have \\(a = 1\\), \\(b = k\\), \\(c = 2k\\)."],
    ["disc",      "The discriminant is \\(b^2 - 4ac = k^2 - 4(1)(2k) = k^2 - 8k\\)."],
    ["ineq",      "For real roots, the discriminant must be non-negative: \\(k^2 - 8k \\geq 0\\)."],
    ["factor",    "Factorising: \\(k(k - 8) \\geq 0\\)."],
    ["sign",      "The product \\(k(k - 8)\\) is non-negative when both factors are non-negative or both are non-positive."],
    ["conclude",  "So the set of possible values is \\(k \\leq 0\\) or \\(k \\geq 8\\)."]
];

proof_steps: random_permutation(proof_steps);

ta: proof("identify", "disc", "ineq", "factor", "sign", "conclude");

opt1a: "The product of two factors is negative when one is positive and the other is negative";
opt1b: "Because k and (2-k) are both negative";
opt1c: "Because k(2-k) was set equal to zero and factorised";
ta1: [[opt1a, true], [opt1b, false], [opt1c, false]];

opt2a: "No -- the discriminant is 2(3) - 3^2 = -3, which is negative, so there are no real roots";
opt2b: "Yes -- k = 3 is positive, so the discriminant is positive";
opt2c: "Yes -- the discriminant is 2(3) - 3^2 = -3, and a negative discriminant means two real roots";
ta2: [[opt2a, true], [opt2b, false], [opt2c, false]];

/* Pick two distinct roots */
r1: rand_with_step(-6, 6, 1);
r1: if r1 = 0 then 1 else r1;
r2: rand_with_step(-6, 6, 1);
r2: if r2 = r1 then r1 + rand_with_step(1, 4, 1) else r2;
r2: if r2 = 0 then -1 else r2;
expr: (x - r1)*(x - r2);
ta1: r1;
ta2: r2;
